$checks=0;function htmlOK(bool $value,string $label):void{global $checks;if(!$value)throw new RuntimeException($label);$checks++;echo "PASS: $label\n";}function htmlDeny(callable $fn,string $label):void{try{$fn();}catch(RuleViolation){htmlOK(true,$label);return;}throw new RuntimeException($label);}function htmlKey():string{return bin2hex(random_bytes(16));}
foreach(['<p>Parágrafo <strong>forte</strong> e <em>itálico</em>.</p>','<h1>TÍTULO</h1><ol start="2" type="A"><li>Item</li></ol>','<table border="1"><thead><tr><th colspan="2">Título</th></tr></thead><tbody><tr><td>A</td><td>B</td></tr></tbody></table>'] as $source){$out=ContractMarkup::prepare($source);htmlOK($out['formato_texto']==='html'&&$out['texto']===$source,'preserva HTML de formatação e estrutura');}
