$model=$models->save((int)$model['idmodelo'],array_replace($modelData,['texto'=>'<h1>Revisado</h1><p><u>[aluno_nome]</u></p>','versao_texto'=>'2','versao'=>$model['versao'],'motivo'=>'Revisão HTML']),htmlKey());htmlOK($model['contratos_atualizados']===1&&str_contains($contracts->detail((int)$b['idcontrato'])['termo_snapshot'],'<u>ALUNO HTML-B</u>'),'modelo HTML atualiza somente o contrato ainda não assinado');htmlOK(array_intersect_key($contracts->detail($id),$frozen)===$frozen,'modelo mantém exatamente HTML, formato e hash assinados');htmlOK($balances===$db->rows('SELECT valor_liquido,saldo_aberto FROM '.$db->table('lancamentos').' ORDER BY idlancamento'),'formatação não altera cobranças');
