$open=$contracts->detail((int)$b['idcontrato']);htmlDeny(fn()=>$contracts->update((int)$b['idcontrato'],['versao'=>$open['versao'],'formato_texto'=>'texto','motivo'=>'Mudar formato'],htmlKey()),'mudar formato exige nova versão do termo');$plain=$contracts->update((int)$b['idcontrato'],['versao'=>$open['versao'],'termo'=>"Texto manual\n[aluno_nome]",'formato_texto'=>'texto','versao_termo'=>'3','motivo'=>'Nova redação'],htmlKey());htmlOK($plain['formato_texto']==='texto'&&str_contains($plain['termo_snapshot'],"Texto manual\nALUNO HTML-B")&&$plain['idmodelo']===null,'edição manual preserva opção de texto simples');
